B.push(
{id:"M3-01",m:3,q:"¿Cuál es el objetivo del principio de transparencia en el mercado de capitales?",o:["Asegurar información veraz, suficiente y oportuna para la toma de decisiones","Igualar la rentabilidad entre inversores minoristas e institucionales","Evitar la volatilidad de los precios","Limitar el acceso de los inversores minoristas a instrumentos complejos"],a:0,e:"Transparencia = información veraz, suficiente y oportuna para que el inversor decida.",r:"M3 · P1"},
{id:"M3-51",m:3,q:"¿Cuál de las siguientes conductas es contraria a la transparencia?",o:["Publicar un hecho relevante en forma inmediata por la AIF","Informar al directorio un conflicto de interés","Difundir información falsa o engañosa sobre valores negociables","Designar un Responsable de Relaciones con el Público"],a:2,e:"Difundir información falsa o engañosa atenta contra la información veraz que busca la transparencia; las otras tres son obligaciones que la cumplen.",r:"M3 · P2"},
{id:"M3-53",m:3,q:"¿Qué documento regula el régimen informativo periódico y ocasional?",o:["Normas CNV Título XII","Normas CNV Título XIII","Normas CNV Título XVI","Normas CNV Título IV"],a:3,e:"El régimen informativo, periódico y ocasional, está en el Título IV de las Normas CNV.",r:"M3 · P3"},
{id:"M3-68",m:3,q:"¿Qué plazo tiene una emisora para informar un hecho relevante?",o:["48 horas","5 días hábiles","24 horas","15 días corridos"],a:2,e:"Para esta pregunta la guía responde 24 horas. Ojo: en la P56, P83 y P101 la guía dice que el hecho relevante se informa en forma inmediata; cada pregunta se contesta con su respuesta oficial.",r:"M3 · P4"},
{id:"M3-07",m:3,q:"¿Qué órgano debe designar un Responsable de Relaciones con el Público Inversor?",o:["El órgano de administración de la emisora","La asamblea de accionistas","La comisión fiscalizadora","El mercado donde listan los valores"],a:0,e:"Lo designa el órgano de administración (directorio).",r:"M3 · P5"},
{id:"M3-54",m:3,q:"¿Dónde se pueden presentar denuncias por incumplimiento de normas de transparencia?",o:["Ante el Banco Central de la República Argentina","Ante el mercado donde cotiza el valor, exclusivamente","Ante la Comisión Nacional de Valores","Ante la Unidad de Información Financiera"],a:2,e:"La CNV es el órgano que recibe las denuncias por incumplimiento de las normas de transparencia.",r:"M3 · P6"},
{id:"M3-28",m:3,q:"¿Qué obligación tienen los participantes respecto al Código de Conducta Profesional?",o:["Actuar con lealtad, diligencia y transparencia frente a clientes y empleadores","Priorizar el interés del empleador sobre el del cliente","Reportar mensualmente su cumplimiento a la CNV","Suscribirlo ante escribano público"],a:0,e:"Lealtad, diligencia y transparencia, tanto con clientes como con empleadores.",r:"M3 · P7"},
{id:"M3-55",m:3,q:"¿Qué norma regula el procedimiento de reclamos y consultas de inversores?",o:["Normas CNV Título XIII","Normas CNV Título IV","Normas CNV Título XII","Normas CNV Título XVI"],a:0,e:"Reclamos y consultas de inversores están en el Título XIII de las Normas CNV.",r:"M3 · P8"},
{id:"M3-56",m:3,q:"¿Qué obligación tienen las emisoras respecto al gobierno corporativo?",o:["Garantizar un dividendo mínimo anual a los accionistas","Someter cada decisión del directorio a aprobación de la CNV","Cumplir con principios de transparencia, equidad y responsabilidad en la gestión","Priorizar la rentabilidad del accionista controlante"],a:2,e:"El gobierno corporativo se apoya en la transparencia, la equidad y la responsabilidad en la gestión.",r:"M3 · P9"},
{id:"M3-69",m:3,q:"¿Qué norma establece el deber de informar conflictos de interés?",o:["Ley 26.831 de Mercado de Capitales, art. 73","Normas CNV Título IV","Ley General de Sociedades, art. 59","Ley General de Sociedades, art. 272"],a:3,e:"El art. 272 de la Ley General de Sociedades obliga al director con interés contrario a hacerlo saber y abstenerse. El art. 59 es el de la lealtad y diligencia.",r:"M3 · P10"},
{id:"M3-70",m:3,q:"¿Qué norma establece el régimen informativo periódico para emisoras?",o:["Normas CNV Título IV","Normas CNV Título XIII","Normas CNV Título II","Normas CNV Título XVI"],a:0,e:"El régimen informativo periódico de las emisoras está en el Título IV de las Normas CNV.",r:"M3 · P11"},
{id:"M3-57",m:3,q:"¿Qué información debe incluir el régimen informativo ocasional?",o:["Los estados contables trimestrales y anuales","El detalle de aranceles y comisiones vigentes","La memoria anual y el reporte del código de gobierno societario","Hechos relevantes y cambios societarios"],a:3,e:"Lo ocasional es lo que surge cuando ocurre: hechos relevantes y cambios societarios. Los estados contables son del régimen periódico.",r:"M3 · P12"},
{id:"M3-71",m:3,q:"¿Qué plazo tiene la emisora para publicar sus estados contables anuales?",o:["30 días corridos","90 días corridos","120 días corridos","60 días corridos"],a:3,e:"Para esta pregunta la guía responde 60 días corridos. Ojo: el módulo IV (P64) da otros plazos (42 días para los trimestrales y 70 para los anuales); acá va el de esta pregunta.",r:"M3 · P13"},
{id:"M3-52",m:3,q:"¿Qué conducta se considera contraria a la transparencia?",o:["Ocultar información relevante para inversores","Publicar los estados contables trimestrales en la AIF","Publicar el detalle de aranceles y comisiones en su página","Atender los reclamos de los clientes a través del RRP"],a:0,e:"Ocultar información relevante priva al inversor de la información suficiente y oportuna que exige la transparencia.",r:"M3 · P14"},
{id:"M3-72",m:3,q:"¿Qué órgano recibe denuncias por incumplimiento de normas de transparencia?",o:["El Banco Central de la República Argentina","La Unidad de Información Financiera","Comisión Nacional de Valores","El mercado en el que listan los valores"],a:2,e:"Las denuncias por incumplimiento de las normas de transparencia las recibe la CNV.",r:"M3 · P15"},
{id:"M3-73",m:3,q:"¿Qué norma regula el procedimiento de reclamos y consultas?",o:["Normas CNV Título XII","Normas CNV Título XIII","Normas CNV Título IV","Normas CNV Título II"],a:1,e:"El procedimiento de reclamos y consultas está en el Título XIII de las Normas CNV.",r:"M3 · P16"},
{id:"M3-74",m:3,q:"¿Qué obligación tienen los participantes respecto al Código de Conducta Profesional?",o:["Actuar con celeridad, reserva y rentabilidad","Suscribirlo anualmente ante la CNV","Actuar con lealtad, diligencia y transparencia","Priorizar las instrucciones del empleador"],a:2,e:"El Código de Conducta Profesional exige actuar con lealtad, diligencia y transparencia.",r:"M3 · P17"},
{id:"M3-59",m:3,q:"¿Qué norma regula el gobierno corporativo en emisoras?",o:["Normas CNV Título II","Normas CNV Título IV","Normas CNV Título XIII","Normas CNV Título XII"],a:3,e:"El gobierno corporativo de las emisoras está en el Título XII de las Normas CNV.",r:"M3 · P18"},
{id:"M3-75",m:3,q:"¿Qué plazo tiene la emisora para informar designación de autoridades?",o:["10 días hábiles","5 días hábiles","15 días hábiles","30 días corridos"],a:0,e:"La designación de autoridades se informa dentro de los 10 días hábiles.",r:"M3 · P19"},
{id:"M3-76",m:3,q:"¿Qué norma establece la obligación de designar un Responsable de Relaciones con el Público Inversor?",o:["Normas CNV Título XVI","Normas CNV Título XIII","Normas CNV Título IV","Normas CNV Título XII"],a:3,e:"La obligación de designar al Responsable de Relaciones con el Público Inversor está en el Título XII de las Normas CNV.",r:"M3 · P20"},
{id:"M3-60",m:3,q:"¿Qué oficina atiende consultas y reclamos de inversores?",o:["La Oficina de Atención al Inversor","La Gerencia de Sumarios de la CNV","La Unidad de Información Financiera","La mesa de entradas del mercado"],a:0,e:"La Oficina de Atención al Inversor (OAI) de la CNV atiende las consultas y reclamos de los inversores.",r:"M3 · P21"},
{id:"M3-77",m:3,q:"¿Qué norma regula la obligación de publicar hechos relevantes?",o:["Normas CNV Título XIII","Normas CNV Título XVI","Normas CNV Título XII","Normas CNV Título IV"],a:3,e:"Los hechos relevantes forman parte del régimen informativo, que está en el Título IV de las Normas CNV.",r:"M3 · P22"},
{id:"M3-78",m:3,q:"¿Qué plazo tiene la emisora para informar un hecho relevante?",o:["24 horas","72 horas","10 días corridos","5 días hábiles"],a:0,e:"Para esta pregunta la guía responde 24 horas. Ojo: en la P56, P83 y P101 la guía da \"en forma inmediata\"; cada pregunta se contesta con su respuesta oficial.",r:"M3 · P23"},
{id:"M3-79",m:3,q:"¿Qué norma establece el deber de informar conflictos de interés?",o:["Ley General de Sociedades, art. 272","Ley 26.831 de Mercado de Capitales, art. 132","Normas CNV Título XII","Ley General de Sociedades, art. 59"],a:0,e:"El deber de informar el conflicto de interés sale del art. 272 de la Ley General de Sociedades.",r:"M3 · P24"},
{id:"M3-58",m:3,q:"¿Qué norma regula las conductas contrarias a la transparencia?",o:["Normas CNV Título IV","Normas CNV Título XIII","Normas CNV Título XII","Normas CNV Título XVI"],a:2,e:"Las conductas contrarias a la transparencia en el ámbito de la oferta pública están en el Título XII de las Normas CNV.",r:"M3 · P25"},
{id:"M3-61",m:3,q:"¿Qué norma establece el procedimiento aplicable ante incumplimiento?",o:["Normas CNV Título IV","Normas CNV Título XII","Normas CNV Título XVI","Normas CNV Título XIII"],a:2,e:"El procedimiento aplicable ante incumplimiento está en el Título XVI de las Normas CNV.",r:"M3 · P26"},
{id:"M3-62",m:3,q:"¿Qué obligación tienen los emisores respecto a inversores institucionales?",o:["Darles la información antes que al resto del público","Informarles sólo lo que pacten por contrato","No brindarles información, porque se presumen informados","Proporcionar información completa y veraz"],a:3,e:"Que el inversor sea institucional no releva al emisor: la información debe ser completa y veraz.",r:"M3 · P27"},
{id:"M3-80",m:3,q:"¿Qué norma regula la recepción y tratamiento de denuncias?",o:["Normas CNV Título XIII","Normas CNV Título XII","Normas CNV Título XVI","Normas CNV Título II"],a:0,e:"La recepción y el tratamiento de denuncias están en el Título XIII de las Normas CNV.",r:"M3 · P28"},
{id:"M3-81",m:3,q:"¿Qué norma establece obligaciones con los clientes y empleadores?",o:["Normas CNV Título IV","Normas CNV Título XIII","Normas CNV Título XII","Normas CNV Título XVI"],a:2,e:"Las obligaciones con clientes y empleadores están en el Título XII de las Normas CNV.",r:"M3 · P29"},
{id:"M3-82",m:3,q:"¿Qué norma regula la Oficina de Atención al Inversor?",o:["Normas CNV Título XII","Normas CNV Título IV","Normas CNV Título II","Normas CNV Título XIII"],a:3,e:"La Oficina de Atención al Inversor está regulada en el Título XIII de las Normas CNV, junto con reclamos, consultas y denuncias.",r:"M3 · P30"},
{id:"M3-02",m:3,q:"¿Qué conductas son contrarias a la transparencia?",o:["La demora en la presentación de estados contables","El abuso de información privilegiada, manipulación y engaño en el mercado","La falta de pago de aranceles al mercado","El incumplimiento del régimen informativo periódico"],a:1,e:"Las tres grandes: abuso de información privilegiada (insider trading), manipulación y engaño.",r:"M3 · P31"},
{id:"M3-15",m:3,q:"A los efectos de la determinación de la sanción de aquellas conductas encuadradas como \"abuso de información privilegiada\" o \"manipulación o engaño\", la CNV considerará como agravante si la conducta irregular fue realizada, entre otros, por:",o:["El accionista de Control","Un inversor minorista con cuenta activa","Un agente productor","Un empleado sin funciones jerárquicas"],a:0,e:"La cercanía al control agrava la sanción: si la conducta la realizó el accionista de control, es agravante.",r:"M3 · P32"},
{id:"M3-83",m:3,q:"A los efectos de la determinación de la sanción referida al abuso de información privilegiada y manipulación y engaño, la CNV considerará como agravante si la conducta sancionada fuere realizada por:",o:["Inversores minoristas sin vínculo alguno con la emisora","Clientes de un agente que operan por cuenta propia","Administradores, gerentes, síndicos de las personas sujetas a fiscalización de la CNV","Empleados administrativos sin funciones jerárquicas"],a:2,e:"Quien administra o fiscaliza a un sujeto controlado por la CNV tiene más acceso y más deber: por eso su conducta es agravante.",r:"M3 · P33"},
{id:"M3-14",m:3,q:"Ante el requerimiento de comparecencia de un investigado (no abogado) por ante la CNV:",o:["Debe concurrir obligatoriamente con patrocinio letrado","No puede concurrir con abogado","Podrá decidir concurrir con o sin asistencia letrada","Debe designar un apoderado matriculado en la CNV"],a:2,e:"La asistencia letrada es optativa en la comparecencia.",r:"M3 · P34"},
{id:"M3-84",m:3,q:"Deber de colaboración de personas sujetas a una investigación:",o:["La persona investigada puede negarse a proveer la información requerida, y esa negativa no puede ser valorada en su contra al decidir la apertura de un sumario","Debe proveer la información sólo una vez formulados los cargos, cuando adquiere el derecho a tomar vista del expediente","Sólo debe proveer información a la CNV si media una orden judicial previa, y la negativa no tiene consecuencias en el sumario","Toda persona sujeta a investigación debe proveer a la CNV la información que le requiera, de manera fehaciente, siendo la conducta renuente y reiterada en contrario un elemento más de convicción en contra para decidir la apertura de un sumario y su resolución final"],a:3,e:"Hay que colaborar y proveer lo que la CNV pida; la renuencia reiterada juega en contra al decidir el sumario y su resolución.",r:"M3 · P35"},
{id:"M3-03",m:3,q:"El plexo normativo referido a la Transparencia en el ámbito de la Oferta Pública resulta oponible:",o:["Sólo a las emisoras y sus directores","Sólo a los agentes registrados ante la CNV","A cualquier persona física o jurídica que intervenga en el mercado de capitales, incluidos los inversores","Únicamente a quienes tengan información privilegiada"],a:2,e:"Alcanza a todos los que intervienen en el mercado, inversores incluidos.",r:"M3 · P36"},
{id:"M3-46",m:3,q:"En cumplimiento del deber de lealtad y diligencia, los directores de las sociedades emisoras deberán:",o:["Priorizar el interés del accionista controlante","Hacer prevalecer, sin excepción, el interés social de la emisora en que ejercen su función y el interés común de todos sus socios","Seguir las instrucciones del comité de auditoría","Consultar cada decisión relevante con la CNV"],a:1,e:"Interés social e interés común de todos los socios, sin excepciones.",r:"M3 · P37"},
{id:"M3-85",m:3,q:"En oportunidad de determinarse la realización de una verificación sobre un sujeto administrado por la CNV, la persona bajo dicho procedimiento de investigación:",o:["Podrá negarse a colaborar hasta que se le formulen cargos","Deberá colaborar únicamente con la documentación contable","Sólo deberá colaborar si media una orden judicial","Deberá colaborar con el Organismo, sin excepciones"],a:3,e:"En una verificación el deber de colaboración con la CNV no tiene excepciones.",r:"M3 · P38"},
{id:"M3-20",m:3,q:"La oferta pública de valores negociables será irregular cuando:",o:["Sea efectuada por sujetos no autorizados por la CNV, o cuando bajo el ropaje de una oferta privada se utilicen medios de comunicación masivos para su difusión","Sólo cuando se coloque por debajo del valor nominal","Sólo cuando no se publique el prospecto en la AIF","Cuando se dirija a inversores calificados del exterior"],a:0,e:"Dos supuestos: falta de autorización o difusión masiva disfrazada de oferta privada.",r:"M3 · P39"},
{id:"M3-86",m:3,q:"La siguiente conducta es contraria a la Transparencia en el ámbito de la Oferta Pública:",o:["Publicación inmediata de hechos relevantes por la AIF","Designación de un Responsable de Relaciones con el Público","Publicación de aranceles y comisiones en la AIF","Engaño y manipulación de mercado"],a:3,e:"El engaño y la manipulación de mercado son conductas contrarias a la transparencia; las otras tres son obligaciones que la cumplen.",r:"M3 · P40"},
{id:"M3-09",m:3,q:"Las denuncias por ante la CNV:",o:["Pueden formularse de manera anónima y/o con individualización de quien denuncia","Deben presentarse siempre con identificación del denunciante","Requieren patrocinio letrado obligatorio","Sólo pueden ser presentadas por inversores con cuenta comitente"],a:0,e:"Se admiten anónimas o con identificación. Y el denunciante no es parte del procedimiento sancionador.",r:"M3 · P41"},
{id:"M3-63",m:3,q:"Las emisoras, los agentes de negociación, los inversores y/o cualquier otro interviniente en los mercados, por sí o por interpósita persona, en ofertas iniciales o mercados secundarios, deberán:",o:["Solicitar autorización previa del mercado antes de cada operación relevante","Limitar su operatoria diaria a un porcentaje del volumen negociado","Abstenerse de realizar prácticas o conductas que pretendan o permitan la manipulación de precios o volumen de los valores negociables listados en Mercados","Abstenerse de operar valores de emisoras vinculadas en todos los casos"],a:2,e:"La prohibición apunta a la manipulación de precios o volumen, y alcanza a todos los intervinientes, en colocación primaria y en secundario.",r:"M3 · P42"},
{id:"M3-12",m:3,q:"Las investigaciones llevadas a cabo en el ámbito de la CNV:",o:["Sólo pueden iniciarse a petición de un particular","Sólo pueden iniciarse de oficio","Pueden iniciarse a petición de un particular o de oficio por parte del Organismo","Únicamente pueden iniciarse por denuncia de un mercado o cámara compensadora"],a:2,e:"Hay dos vías: la petición de un particular o la iniciativa de oficio de la propia CNV.",r:"M3 · P43"},
{id:"M3-23",m:3,q:"Los domicilios especiales constituidos ante la CNV por los directores de sociedades en oferta pública para recibir notificaciones tienen validez:",o:["Hasta la cesación del cargo","Hasta DOS (2) años después de que cesan en sus cargos","Hasta CINCO (5) años después de la cesación","Indefinidamente"],a:1,e:"2 años posteriores al cese en el cargo.",r:"M3 · P44"},
{id:"M3-87",m:3,q:"Los mercados, respecto de los agentes que operen bajo su órbita:",o:["Deben efectuar amplias tareas de inspección y control","Sólo deben controlarlos cuando la CNV se lo pida","No tienen facultades de control, que son sólo de la CNV","Deben limitarse a verificar su inscripción anual"],a:0,e:"Los mercados tienen a su cargo amplias tareas de inspección y control sobre sus agentes.",r:"M3 · P45"},
{id:"M3-64",m:3,q:"Los sujetos que ofrezcan, compren, vendan o realicen cualquier tipo de operación sobre valores negociables por cuenta y orden de terceros:",o:["Sólo requieren un poder especial otorgado por el cliente","Deben inscribirse únicamente en el mercado donde operan","Deben estar registrados ante el Organismo","Pueden operar libremente si el monto no supera un umbral"],a:2,e:"Operar por cuenta de terceros exige estar registrado ante el Organismo, es decir, la CNV.",r:"M3 · P46"},
{id:"M3-19",m:3,q:"Resultan susceptibles de calificarse como supuestos de engaños al mercado:",o:["Las transacciones en las que no se produzca, más allá de su apariencia, la transferencia de los valores, y las efectuadas para crear la apariencia falsa de oferta y demanda o de un mercado activo, aun cuando se produzca efectivamente la transferencia","Sólo las operaciones simuladas sin transferencia real","Sólo las operaciones que producen variaciones de precio superiores al 10%","Las operaciones realizadas fuera del horario de rueda"],a:0,e:"Ambas modalidades: con o sin transferencia efectiva, si el propósito es aparentar un mercado activo.",r:"M3 · P47"},
{id:"M3-16",m:3,q:"No se considera abuso de información privilegiada por parte del director de una sociedad emisora:",o:["La comunicación de dicha información a terceros, en el ejercicio normal de su cargo","Comprar acciones antes de que se publique el balance","Recomendar a un amigo la compra basándose en el dato reservado","Vender su tenencia conociendo una pérdida no divulgada"],a:0,e:"La comunicación en el ejercicio normal del cargo está excluida; todo lo demás es abuso.",r:"M3 · P48"},
{id:"M3-21",m:3,q:"Puede efectuar una invitación al público en general para comprar y vender valores negociables:",o:["Cualquier persona con conocimientos acreditados","Cualquier sociedad anónima inscripta en el Registro Público","Sólo aquellas personas físicas o jurídicas que previamente hayan obtenido autorización de la CNV","Los idóneos, aun sin estar vinculados a un agente"],a:2,e:"Se requiere autorización previa; quien no la tiene comete oferta irregular.",r:"M3 · P49"},
{id:"M3-10",m:3,q:"Quien/es formula/n una denuncia por ante la CNV y las personas físicas y/o jurídicas denunciadas e investigadas:",o:["El denunciante es parte del proceso sancionador y puede tomar vista del expediente desde el inicio; el denunciado es parte desde la apertura de la investigación","El denunciante no es parte, pero puede tomar vista del expediente; el denunciado sólo es parte a partir de la resolución final","Quien denuncia no es parte del proceso sancionador ni puede tomar vista del expediente; el denunciado no es parte hasta la formulación de cargos, y sólo desde ahí puede tomar vista y ejercer su defensa","Ambos son parte desde la presentación de la denuncia y pueden tomar vista del expediente en cualquier momento"],a:2,e:"La denuncia es un hecho externo al procedimiento: el denunciante nunca es parte, y el denunciado lo es recién con la formulación de cargos.",r:"M3 · P50"},
{id:"M3-17",m:3,q:"Quienes en razón de su cargo o actividad tengan información acerca de un hecho no divulgado públicamente y que por su importancia sea apto para afectar la colocación de valores negociables, o el curso de su negociación en los mercados, deberán guardar estricta reserva:",o:["Durante 30 días","Hasta que lo autorice el mercado","Hasta el cierre del ejercicio","Hasta que dicha información tenga carácter público"],a:3,e:"La reserva se mantiene hasta que la información se hace pública.",r:"M3 · P51"},
{id:"M3-88",m:3,q:"Se considera oferta pública irregular:",o:["Sólo la colocación de valores por debajo de su valor nominal","Cualquier tipo de actuación relacionada con valores negociables efectuada por personas humanas o jurídicas sin autorización ante la CNV","La oferta dirigida exclusivamente a inversores calificados","La emisión de valores sin aviso en un diario de circulación nacional"],a:1,e:"Lo que vuelve irregular a la oferta es actuar con valores negociables sin autorización de la CNV.",r:"M3 · P52"},
{id:"M3-13",m:3,q:"Toda persona sujeta a un procedimiento de investigación y/o inspección:",o:["Puede negarse a declarar sin consecuencias","Puede exigir que el requerimiento se curse por el mercado","Sólo responde ante requerimiento judicial","Deberá proveer a la CNV toda la información y documentación que ésta le requiera"],a:3,e:"Deber de colaboración: la conducta renuente y reiterada es un elemento de convicción en contra al decidir la apertura del sumario.",r:"M3 · P53"},
{id:"M3-24",m:3,q:"Las Cámaras Compensadoras y los mercados deben denunciar ante la CNV toda falta en que incurrieren sus agentes miembros:",o:["Siempre","Sólo si la falta genera perjuicio a inversores","Sólo cuando la falta sea reiterada","Sólo si el agente no la subsana en el plazo que le fijen"],a:0,e:"El deber de denunciar las faltas de sus agentes miembros ante la CNV no tiene excepciones.",r:"M3 · P54"},
{id:"M3-89",m:3,q:"Los administradores de emisoras en oferta pública, los integrantes del órgano de fiscalización y los administradores de mercados, cámaras compensadoras y demás agentes registrados ante la CNV (y sus órganos de fiscalización, en materia de su competencia) deberán informar a la CNV en forma inmediata:",o:["Despidos de trabajadores, con causa o sin ella, que representen un 10% del número total que prestan servicios en la entidad, y hechos de cualquier naturaleza y acontecimientos fortuitos que obstaculicen o puedan obstaculizar seriamente el desenvolvimiento de sus actividades, incluyendo afectaciones de importancia al ambiente, con sus consecuencias","Despidos de trabajadores, con o sin causa, que representen un 5% del total, y cualquier cambio en la composición del personal jerárquico","Sólo los despidos sin causa que superen el 20% del personal, y los hechos fortuitos una vez que la actividad quedó paralizada","Cualquier despido de personal, y los acontecimientos fortuitos sólo cuando ya hayan generado pérdidas registradas en los estados contables"],a:0,e:"Dos supuestos de informe inmediato: despidos que lleguen al 10% del personal y hechos o acontecimientos fortuitos que traben seriamente la actividad, ambientales incluidos.",r:"M3 · P55"},
{id:"M3-04",m:3,q:"¿En cuánto tiempo debe informar un sujeto regulado por la CNV un hecho relevante?",o:["Inmediatamente","Dentro de los 5 días hábiles","Dentro de las 72 horas","Con la presentación de los estados contables trimestrales"],a:0,e:"Para esta pregunta la guía responde inmediatamente. Ojo: en la P4 y la P23 la guía da 24 horas; cada pregunta se contesta con su respuesta oficial.",r:"M3 · P56"},
{id:"M3-90",m:3,q:"Las emisoras, las cámaras compensadoras, los agentes de negociación y toda otra persona humana o jurídica que intervenga, se ofrezca u ofrezca servicios en la oferta pública de valores negociables deberán especialmente abstenerse de:",o:["Atender consultas de inversores a través de su Responsable de Relaciones con el Público","Publicar sus aranceles y comisiones en la AIF y en su página institucional","Ofrecer servicios de asesoramiento de valores negociables sin contar con el registro en cualquiera de las categorías de Agentes autorizados por la CNV a tales efectos","Ofrecer asesoramiento a inversores institucionales aun contando con el registro de Agente correspondiente"],a:2,e:"Asesorar sobre valores negociables exige estar registrado en alguna categoría de Agente; sin ese registro hay que abstenerse.",r:"M3 · P57"},
{id:"M3-91",m:3,q:"Los inversores y/o cualquier otro interviniente en los Mercados, en ofertas iniciales o mercados secundarios, deberán:",o:["Abstenerse de operar valores de baja liquidez y de efectuar transacciones fuera del horario de rueda","Abstenerse de efectuar transacciones con transferencia efectiva que busquen crear la apariencia falsa de oferta y demanda o de un mercado activo, y de efectuar transacciones en las que no se produzca, más allá de su apariencia, la transferencia de los valores","Abstenerse sólo de las transacciones sin transferencia real; si la transferencia se produce, la operación es válida cualquiera sea su propósito","Informar a la CNV toda operación que mueva el precio más de un 10% y abstenerse de operar en la apertura"],a:1,e:"Se prohíben las dos formas de aparentar mercado: con transferencia efectiva hecha para simular oferta y demanda, y sin transferencia real.",r:"M3 · P58"},
{id:"M3-29",m:3,q:"La Oficina de Atención al Inversor (OAI) de la CNV:",o:["Promueve la educación sobre el Mercado de Capitales, atiende consultas de inversores y público en general y pone a disposición las recomendaciones y advertencias de la CNV y otros reguladores, como OICV-IOSCO y ESMA","Resuelve arbitralmente los conflictos entre inversores y agentes","Autoriza las ofertas públicas","Fiscaliza a los auditores externos"],a:0,e:"Tres funciones: educación, consultas y difusión de recomendaciones y advertencias propias y de otros reguladores.",r:"M3 · P59"},
{id:"M3-92",m:3,q:"La idoneidad que acredita el examen de la CNV es parte de los requisitos para:",o:["Inscribirse como Agente de Liquidación y Compensación","Operar por cuenta propia sin intermediación de un Agente","Integrar el directorio de una emisora en oferta pública","Desempeñarse como idóneo en los Agentes y Fondos Comunes de Inversión"],a:3,e:"El examen es un requisito para trabajar como idóneo en Agentes y FCI; no alcanza por sí solo, porque además hay que estar inscripto.",r:"M3 · P60"},
{id:"M3-36",m:3,q:"En el marco de la normativa aplicable a la actividad del idóneo, ¿cuál de las siguientes afirmaciones describe de manera correcta la atribución de responsabilidad en caso de incumplimientos normativos detectados durante su desempeño?",o:["Sólo responde el Agente que lo empleó","La responsabilidad es exclusivamente penal","La CNV podrá imponer sanciones al idóneo por incumplimientos normativos y esta responsabilidad podrá extenderse también al Agente y sus integrantes, según los procedimientos establecidos","Responde el mercado donde opera el agente"],a:2,e:"El idóneo responde por sus incumplimientos, sin perjuicio de la responsabilidad del Agente y sus integrantes.",r:"M3 · P61"},
{id:"M3-32",m:3,q:"Deberán inscribirse en el Registro de Idóneos llevado por la CNV:",o:["Todos los empleados de un agente registrado","Sólo quienes atienden a inversores calificados","Sólo los operadores de mesa","Aquellas personas que desarrollen la actividad de venta, promoción o prestación de cualquier tipo de asesoramiento en el contacto con el público inversor"],a:3,e:"El criterio es el contacto con el público inversor para vender, promover o asesorar.",r:"M3 · P62"},
{id:"M3-30",m:3,q:"¿Dónde puede un inversor verificar si el Agente con el que planea invertir está autorizado por la CNV?",o:["En la página del mercado donde opera el agente","Consultando el Registro Público de Agentes autorizados y registrados ante la CNV, en el sitio web de la CNV","En el Registro Público de Comercio de su jurisdicción","En el registro de la UIF"],a:1,e:"Registro público de agentes, en el sitio de la CNV. Los prospectos, en cambio, están en la AIF.",r:"M3 · P63"},
{id:"M3-93",m:3,q:"Se presenta un cliente que posee Acciones de una emisora autorizada, quien quiere consultar los prospectos de emisión. ¿Dónde puede encontrar dicha información pública el inversor?",o:["En el Registro Público de Comercio de la jurisdicción de la emisora","Sólo solicitándolos por nota a la sociedad emisora","En la Autopista de la Información Financiera, en el link de la emisora correspondiente","En el boletín diario del mercado donde se negocian las acciones"],a:2,e:"Los prospectos son información pública y están en la AIF, dentro del link de cada emisora.",r:"M3 · P64"},
{id:"M3-38",m:3,q:"Según la normativa, ¿con qué frecuencia debe actualizarse el perfil de riesgo del cliente?",o:["Al menos una vez al año, o en la primera oportunidad que el cliente pretenda operar después de dicho plazo","Cada tres años","Sólo al abrir la cuenta comitente","Cada vez que el cliente opera"],a:0,e:"Anual, o al primer intento de operar vencido el plazo.",r:"M3 · P65"},
{id:"M3-34",m:3,q:"Según la normativa vigente, ¿qué debe ocurrir para que un idóneo inactivo sea dado de baja definitiva del Registro de Idóneos y deba cumplir nuevamente con los requisitos para obtener la idoneidad?",o:["Permanecer inactivo por dos años o no cumplir con los cursos de actualización requeridos","Permanecer inactivo por seis meses","No renovar su matrícula anual","Cambiar de agente empleador"],a:0,e:"Dos años de inactividad o incumplimiento de la capacitación de actualización.",r:"M3 · P66"},
{id:"M3-33",m:3,q:"Idoneidad en el Mercado de Capitales:",o:["Alcanza con aprobar el examen de la CNV, sin alta de un Agente; el idóneo debe lealtad a su empleador por sobre los inversores; y ante incumplimientos responde únicamente el Agente que lo contrató","Hay que ser dado de alta por un mercado; el idóneo puede operar por cuenta propia con la sola aprobación del examen; y la responsabilidad por sus incumplimientos recae sólo en el mercado","La inscripción la tramita el propio postulante ante la CNV; el idóneo debe actuar con diligencia sólo frente a inversores institucionales; y sus incumplimientos se sancionan exclusivamente en sede penal","Hay que ser dado de alta en el Registro Público de Idóneos de la CNV por un Agente Matriculado; el idóneo debe actuar con honestidad, imparcialidad, profesionalidad, diligencia y lealtad con los inversores, velando por la gestión sana y prudente; y ante incumplimientos es pasible de las sanciones del art. 132 de la Ley 26.831, sin perjuicio de la responsabilidad del Agente y sus integrantes"],a:3,e:"Tres ideas: el alta la pide un Agente, el idóneo se debe a los inversores con honestidad y lealtad, y responde por sus incumplimientos (art. 132 de la Ley 26.831) sin perjuicio de la responsabilidad del Agente.",r:"M3 · P67"},
{id:"M3-31",m:3,q:"¿A dónde puede recurrir un inversor para consultar su tenencia de valores negociables?",o:["Al Agente de Depósito Colectivo, por los medios que éste habilite, debiendo el Agente informar al comitente de los mismos","Únicamente a su ALyC","A la CNV, mediante nota","Al mercado donde se negociaron los valores"],a:0,e:"El agente de depósito colectivo informa la tenencia al comitente, por los medios que habilite.",r:"M3 · P68"},
{id:"M3-08",m:3,q:"El Responsable de Relaciones con el Público (RRP) del Agente deberá:",o:["Atender los reclamos y denuncias de los clientes, informarlos al órgano de administración y remitir un informe dentro de los 5 días hábiles de recibido cada reclamo/denuncia, con un detalle del estado y las acciones adoptadas","Aprobar las órdenes de los clientes de riesgo alto","Reportar las operaciones sospechosas a la UIF","Auditar el cumplimiento del código de conducta"],a:0,e:"El RRP atiende reclamos y denuncias, los informa al órgano de administración y remite el informe dentro de los 5 días hábiles.",r:"M3 · P69"},
{id:"M3-65",m:3,q:"Es condición suficiente para ejercer como idóneo:",o:["Haber aprobado el examen de idoneidad de la CNV","Contar con título universitario en ciencias económicas","Estar inscripto en el registro público de idóneos de la CNV","Tener dos años de antigüedad en un Agente registrado"],a:2,e:"Lo que habilita es la inscripción en el registro público de idóneos; aprobar el examen es un requisito, pero no alcanza por sí solo.",r:"M3 · P70"},
{id:"M3-25",m:3,q:"De acuerdo al Título de Transparencia en el Ámbito de la Oferta Pública de las Normas CNV, sobre publicidad y propaganda:",o:["La CNV no tiene competencia sobre la publicidad de los agentes","La publicidad no debe inducir a error, equívocos o confusión respecto a la naturaleza, precios, rentabilidad o garantías de los valores negociables, y en caso de violación la CNV puede ordenar su modificación o suspensión, además de aplicar otras sanciones","Basta con incluir una leyenda de riesgo al pie","Sólo se controla la publicidad de FCI"],a:1,e:"Control pleno: modificación, suspensión y sanciones.",r:"M3 · P71"},
{id:"M3-37",m:3,q:"¿Cuáles son los aspectos mínimos que un agente debe considerar al conocer el perfil de riesgo de sus clientes y qué excepciones establece la normativa para la aplicación de este requisito?",o:["La experiencia en inversiones, el conocimiento sobre instrumentos, el objetivo de inversión, la situación financiera, el horizonte de inversión, el porcentaje de ahorros destinado a la inversión, el nivel de ahorro que está dispuesto a arriesgar y otras circunstancias relevantes; no aplica a inversores institucionales","Únicamente el monto disponible para invertir; no aplica a clientes con cuenta en dólares","Sólo la edad y la ocupación del cliente; no aplica a menores de edad","El perfil tributario informado a la autoridad fiscal; no tiene excepciones"],a:0,e:"La excepción expresa: no se aplica a inversores institucionales.",r:"M3 · P72"},
{id:"M3-35",m:3,q:"¿Quiénes no pueden ser inscriptos como idóneos de los Agentes registrados en la Comisión?",o:["Quienes no tengan título universitario","Los menores de 21 años","Las personas que no puedan ejercer el comercio, los fallidos, los concursados y las personas inhabilitadas por el BCRA, hasta cinco años después de su rehabilitación","Quienes trabajen simultáneamente en dos agentes"],a:2,e:"Inhabilitaciones comerciales y del BCRA, con el plazo de 5 años posteriores a la rehabilitación.",r:"M3 · P73"},
{id:"M3-50",m:3,q:"¿Qué obligación tienen los mercados, cámaras compensadoras y demás agentes registrados respecto a la publicación de los derechos, aranceles y comisiones que perciben?",o:["Informarlos anualmente a la CNV","No están obligados a publicarlos","Comunicarlos por escrito a cada cliente","Publicar y mantener actualizado el detalle en la Autopista de la Información Financiera y de forma idéntica en su página institucional, en un lugar destacado"],a:3,e:"Doble publicación: AIF + sitio institucional, con idéntico contenido y en lugar destacado.",r:"M3 · P74"},
{id:"M3-27",m:3,q:"Las personas físicas y/o jurídicas registradas en la Comisión deberán contar con un Código de Protección al Inversor o Código de Conducta. ¿Cuáles son los aspectos mínimos que dicho Código debe abarcar?",o:["Sólo las normas de prevención de lavado de activos y el régimen de comisiones vigente","La normativa de Transparencia en el Ámbito de la Oferta Pública, las conductas contrarias y los procedimientos para prevenirlas; las normas de protección al inversor, incluidos los derechos de los pequeños inversores minoristas y cómo ejercerlos; y las disposiciones sobre el comportamiento del personal, con seguridad y eficiencia en los servicios, confidencialidad y prevención de conflictos de interés","Únicamente el régimen de comisiones y aranceles","El organigrama y las funciones de cada área"],a:1,e:"Tres bloques: transparencia, protección al inversor y comportamiento del personal.",r:"M3 · P75"},
{id:"M3-18",m:3,q:"En el marco de las obligaciones de los participantes en el ámbito de la oferta pública, ¿quiénes están comprendidos en el deber de guardar estricta reserva sobre información no divulgada públicamente que pueda afectar la colocación de valores negociables o su negociación en los mercados?",o:["Sólo los directores y síndicos de la emisora, mientras duren en sus cargos","Sólo los auditores externos y los agentes de calificación de riesgos","Sólo los agentes registrados y sus idóneos","Los directores, administradores, gerentes, síndicos, miembros del consejo de vigilancia, accionistas controlantes y profesionales intervinientes de cualquier entidad autorizada a la oferta pública, incluidos los Mercados; quien haga una oferta pública de adquisición o canje sobre esa entidad; directivos, funcionarios y empleados de los agentes de calificación de riesgos; y funcionarios públicos y directivos, funcionarios y empleados de los organismos de control públicos o privados, incluida la CNV"],a:3,e:"El círculo de obligados es muy amplio e incluye a los propios funcionarios de la CNV.",r:"M3 · P76"},
{id:"M3-66",m:3,q:"En caso de que un accionista desee participar en una asamblea, debe informar su intención de asistir y depositar sus acciones ante:",o:["La Comisión Nacional de Valores","El mercado donde listan las acciones","El agente de liquidación y compensación del accionista","La sociedad emisora"],a:3,e:"La comunicación de asistencia y el depósito de las acciones se hacen ante la propia sociedad emisora.",r:"M3 · P77"},
{id:"M3-94",m:3,q:"¿Deben cumplir con algún procedimiento específico las sociedades que hagan oferta pública de sus acciones sobre los actos o contratos que celebren con una parte relacionada?",o:["No, rige la libre decisión del directorio","Sí, en todos los casos, cualquiera sea el monto","Sí, siempre que se trate de un monto relevante estipulado en la Ley de Mercado de Capitales","Sólo si la parte relacionada es el accionista controlante"],a:2,e:"El procedimiento para partes relacionadas se activa cuando el monto es relevante según la Ley de Mercado de Capitales.",r:"M3 · P78"},
{id:"M3-06",m:3,q:"La normativa ejemplifica también como \"hechos relevantes\" enmarcados en el deber de informar a:",o:["Los cambios en el objeto social, alteraciones de importancia en sus actividades o iniciación de otras nuevas, y las pérdidas superiores al 15% del patrimonio neto","Cualquier variación del precio de la acción mayor al 5%","La renuncia de cualquier empleado jerárquico","El cambio de auditor externo únicamente"],a:0,e:"Dos ejemplos que da la guía: cambios de objeto o de actividad y pérdidas de más del 15% del patrimonio neto.",r:"M3 · P79"},
{id:"M3-49",m:3,q:"En el régimen general de la oferta pública, una sociedad emisora no puede prescindir de publicar a través de la AIF:",o:["Las actas de las asambleas anuales de la entidad y los estados contables trimestrales de la sociedad","Sólo la memoria anual","Sólo los hechos relevantes","El listado de accionistas"],a:0,e:"Actas de asamblea y estados contables trimestrales van sí o sí por la AIF.",r:"M3 · P80"},
{id:"M3-95",m:3,q:"¿Qué tipo de emisoras están obligadas a presentar un Código de Gobierno Societario?",o:["Las emisoras comprendidas en el régimen general de oferta pública por acciones u obligaciones negociables","Sólo las emisoras PyME CNV","Únicamente las emisoras de fideicomisos financieros","Todas las sociedades anónimas inscriptas, hagan o no oferta pública"],a:0,e:"Lo presentan las emisoras del régimen general, tanto por acciones como por obligaciones negociables.",r:"M3 · P81"},
{id:"M3-05",m:3,q:"¿Qué se considera un hecho relevante?",o:["Toda decisión del directorio, cualquiera sea su alcance","Sólo los cambios en el capital social","Todo hecho o situación que, por su importancia, sea apto para afectar en forma sustancial la colocación de los valores negociables, el curso de su negociación, o el desenvolvimiento de la actividad propia de cada sujeto alcanzado","Sólo los hechos que la CNV requiera expresamente"],a:2,e:"El criterio es la aptitud del hecho para afectar sustancialmente la colocación, la negociación o la actividad.",r:"M3 · P82"},
{id:"M3-96",m:3,q:"¿En qué oportunidad debe ser comunicado un hecho relevante?",o:["Dentro de los 5 días hábiles de ocurrido","Con los próximos estados contables trimestrales","En la próxima asamblea anual","En forma inmediata de ocurrido"],a:3,e:"Para esta pregunta la guía responde \"en forma inmediata de ocurrido\". Ojo: en la P4 y la P23 la guía da 24 horas; cada pregunta se contesta con su respuesta oficial.",r:"M3 · P83"},
{id:"M3-41",m:3,q:"¿Qué emisoras están obligadas a contar con un Comité de Auditoría?",o:["Todas las sociedades anónimas, hagan o no oferta pública","Las emisoras que hacen oferta pública de acciones","Sólo las emisoras PyME CNV","Únicamente las emisoras de obligaciones negociables simples"],a:1,e:"El Comité de Auditoría es obligatorio para las emisoras que hacen oferta pública de acciones.",r:"M3 · P84"},
{id:"M3-97",m:3,q:"El Comité de Auditoría debe estar conformado por:",o:["Síndicos","Auditores externos","Directores","Accionistas"],a:2,e:"El Comité de Auditoría se forma con directores (y la mayoría tiene que ser independiente).",r:"M3 · P85"},
{id:"M3-98",m:3,q:"La mayoría de los miembros del Comité de Auditoría deben reunir el carácter de:",o:["Directores Independientes","Síndicos","Contadores públicos matriculados","Accionistas minoritarios"],a:0,e:"Los miembros son directores, y la mayoría de ellos tiene que ser independiente.",r:"M3 · P86"},
{id:"M3-67",m:3,q:"¿Qué es el gobierno societario?",o:["El conjunto de prácticas, procesos y estructuras por el cual se dirigen y controlan las compañías","El conjunto de normas contables con que se confeccionan los estados financieros","El órgano de la emisora encargado de fiscalizar al directorio","El reglamento de la CNV que fija las sanciones a las emisoras"],a:0,e:"Gobierno societario son las prácticas, procesos y estructuras con que se dirige y controla una compañía; el Código es la herramienta para reportarlas.",r:"M3 · P87"},
{id:"M3-42",m:3,q:"¿Qué es un código de gobierno societario?",o:["Una herramienta de reporte de buenas prácticas corporativas que deben presentar las emisoras del régimen general","Un reglamento interno que la CNV aprueba a cada emisora","Un manual de procedimientos operativos del directorio","Un contrato entre accionistas inscripto en el Registro Público"],a:0,e:"El Código es una herramienta de reporte de buenas prácticas, que presentan las emisoras del régimen general.",r:"M3 · P88"},
{id:"M3-99",m:3,q:"¿Con qué periodicidad debe presentarse el reporte al código de gobierno societario?",o:["Trimestralmente, junto con los estados contables","Cada tres años, ante la asamblea extraordinaria","Anualmente, como anexo en la Memoria Anual","Semestralmente, por la AIF"],a:2,e:"El reporte del Código de Gobierno Societario es anual y va como anexo de la Memoria.",r:"M3 · P89"},
{id:"M3-43",m:3,q:"¿Las prácticas dispuestas en el Código de Gobierno Societario de la CNV son obligatorias para las emisoras alcanzadas?",o:["Sí, su incumplimiento genera sanción automática","No, y tampoco deben informar nada al respecto","Sí, salvo para las PyME CNV","No, no son obligatorias pero la emisora deberá brindar explicaciones sobre cómo cumple con los principios de gobierno corporativo que subyacen a la práctica"],a:3,e:"Esquema \"cumplir o explicar\": no son obligatorias, pero hay que fundamentar.",r:"M3 · P90"},
{id:"M3-26",m:3,q:"La afirmación: \"La publicidad realizada para la promoción y comercialización del Fondo, con independencia del medio empleado, no podrá en ningún caso ser dirigida de forma específica y/o exclusiva a los menores de edad, debiendo garantizar la difusión de idéntico contenido e información a todo el público inversor\", es:",o:["Verdadera","Falsa","Verdadera sólo para fondos de renta variable","Falsa: no existe regulación sobre publicidad de FCI"],a:0,e:"Verdadera: debe garantizarse idéntico contenido e información a todo el público inversor.",r:"M3 · P91"},
{id:"M3-39",m:3,q:"¿A partir de qué edad un ALyC puede abrir subcuentas comitentes a nombre de una persona menor de edad, según la normativa vigente?",o:["A partir de los 16 años","A partir de los 13 años","A partir de los 18 años","No puede en ningún caso"],a:1,e:"Desde los 13 años (RG 1023/2024), con operatoria limitada.",r:"M3 · P92"},
{id:"M3-100",m:3,q:"Según la normativa vigente, ¿qué tipo de operaciones pueden realizar los menores de edad adolescentes titulares de subcuentas comitentes?",o:["Cualquier operación, con autorización de sus padres","Sólo suscripciones de FCI de renta variable","Operaciones de contado y venta en corto","Únicamente operaciones de contado y caución colocadora"],a:3,e:"Los adolescentes sólo pueden hacer contado y caución colocadora.",r:"M3 · P93"},
{id:"M3-101",m:3,q:"¿Con qué periodicidad debe remitir el RRP a la CNV por Autopista de la Información Financiera el detalle de reclamos/denuncias?",o:["Dentro de los 5 días hábiles de recibidos y actualizaciones semanales hasta su cierre","Dentro de los 10 días hábiles de recibidos y actualizaciones mensuales","Mensualmente, en un reporte consolidado","Dentro de los 5 días hábiles de recibidos, sin actualizaciones posteriores"],a:0,e:"Primero el detalle dentro de los 5 días hábiles, y después actualizaciones semanales hasta que se cierre.",r:"M3 · P94"},
{id:"M3-48",m:3,q:"En las sociedades comprendidas en el régimen de oferta pública por acciones o valores negociables de deuda:",o:["La Comisión Fiscalizadora debe tener mayoría de miembros independientes","La Comisión Fiscalizadora se reemplaza por el comité de auditoría","La Comisión Fiscalizadora no requiere independencia","La totalidad de los miembros de la Comisión Fiscalizadora debe revestir la calidad de independiente"],a:3,e:"La totalidad de los síndicos debe ser independiente. En el comité de auditoría, en cambio, alcanza con la mayoría.",r:"M3 · P95"},
{id:"M3-47",m:3,q:"Según el art. 73 de la Ley 26.831, los contratos con partes relacionadas, siempre que las condiciones previstas hayan sido calificadas como razonablemente adecuadas por los órganos competentes, requieren obligatoriamente de:",o:["La aprobación del Directorio con indicación de la existencia de los pronunciamientos del comité de auditoría o, en su caso, de las firmas evaluadoras independientes","Aprobación de la asamblea extraordinaria","Autorización previa de la CNV","Dictamen de la comisión fiscalizadora únicamente"],a:0,e:"Aprobación del directorio respaldada por el comité de auditoría o evaluadoras independientes.",r:"M3 · P96"},
{id:"M3-45",m:3,q:"Según el art. 59 de la Ley 19.550, ¿qué tipo de responsabilidad les cabe, por los daños y perjuicios causados, a los administradores y representantes de la sociedad que faltaren a sus obligaciones de lealtad y diligencia?",o:["Limitada al monto de su remuneración","Sólo penal","Ilimitada y solidaria por acción u omisión","Subsidiaria respecto de la sociedad"],a:2,e:"Ilimitada y solidaria, por acción u omisión, por los daños y perjuicios causados.",r:"M3 · P97"},
{id:"M3-44",m:3,q:"Según el art. 272 de la Ley 19.550, si un director tuviese un interés contrario al de la sociedad:",o:["Debe renunciar al cargo","Deberá hacerlo saber al directorio y a los síndicos, y abstenerse de intervenir en la deliberación","Puede votar si lo informa por escrito","Debe transferir sus acciones antes de la reunión"],a:1,e:"Informar + abstenerse. Es el deber de conducta frente al conflicto de interés.",r:"M3 · P98"},
{id:"M3-22",m:3,q:"RG 1002/2024. ¿Cuál de las siguientes sí es una conducta contraria a la transparencia?",o:["Ofrecer servicios de asesoramiento en valores sin la categoría de Agente habilitada por la CNV","Publicar el prospecto fuera de plazo","Cobrar comisiones superiores a las del mercado","Operar en el segmento bilateral"],a:0,e:"Asesorar sin la categoría de Agente habilitada es conducta contraria a la transparencia según la RG 1002/2024.",r:"M3 · P99"},
{id:"M3-102",m:3,q:"RG 1002/2024. Además del asesoramiento no autorizado, ¿qué otra conducta debe abstenerse de realizar una persona no registrada?",o:["Invertir su propio patrimonio a través de un Agente registrado","Presentar denuncias anónimas ante la CNV","Realizar actividades de difusión y/o captación de clientes para Agentes registrados sin autorización","Consultar el Registro Público de Agentes en el sitio de la CNV"],a:2,e:"Sin autorización tampoco se puede difundir ni captar clientes para Agentes registrados; las otras tres son cosas que cualquiera puede hacer.",r:"M3 · P100"},
{id:"M3-103",m:3,q:"Los hechos relevantes deben informarse:",o:["Dentro de los 5 días hábiles, por nota a la CNV","En forma inmediata, sólo por la página web de la emisora","Con los estados contables trimestrales, por la AIF","En forma inmediata, por Autopista de la Información Financiera"],a:3,e:"Para esta pregunta la guía responde: en forma inmediata y por la AIF. Ojo: en la P4 y la P23 la guía da 24 horas; cada pregunta se contesta con su respuesta oficial.",r:"M3 · P101"},
{id:"M3-104",m:3,q:"El RRP debe enviar a la CNV por Autopista de la Información Financiera el detalle de cada reclamo/denuncia:",o:["Mensualmente, con un resumen de todos los reclamos del período","Dentro de los 15 días hábiles de recibido, sin actualizaciones","Dentro de los 5 días hábiles de recibido, con actualizaciones semanales hasta el cierre","Sólo una vez cerrado el reclamo, con su resolución final"],a:2,e:"5 días hábiles para el detalle inicial por la AIF, y después actualizaciones semanales hasta el cierre.",r:"M3 · P102"},
{id:"M3-40",m:3,q:"RG 1023/2024: los menores de entre 13 y 17 años con subcuenta comitente pueden:",o:["Operar de contado, caución tomadora y futuros","Operar cualquier instrumento con la firma de sus representantes","Operar sólo FCI, sin acceso al contado","Operar de contado (renta fija/variable) y caución colocadora"],a:3,e:"Contado de renta fija o variable y caución colocadora; nada de tomar caución ni derivados.",r:"M3 · P103"},
{id:"M3-105",m:3,q:"En sociedades con OP de acciones, el Comité de Auditoría:",o:["Debe estar integrado por síndicos, en su totalidad independientes","Debe estar integrado por auditores externos designados por la asamblea","Debe estar integrado por Directores, con mayoría de Independientes","Debe estar integrado por Directores, todos ellos independientes"],a:2,e:"Directores, con mayoría de independientes. La totalidad independiente es la regla de la Comisión Fiscalizadora, no del Comité.",r:"M3 · P104"},
{id:"M3-106",m:3,q:"El Código de Gobierno Societario (CGS) se presenta:",o:["Anualmente, como anexo de la Memoria","Trimestralmente, como anexo de los estados contables","Cada dos años, con la renovación del directorio","Sólo una vez, al ingresar al régimen de oferta pública"],a:0,e:"El CGS se reporta una vez por año, como anexo de la Memoria.",r:"M3 · P105"},
{id:"M3-107",m:3,q:"¿Cuál de las siguientes constituye oferta irregular?",o:["Colocar obligaciones negociables autorizadas a través de un ALyC registrado","Publicar un prospecto aprobado en la AIF","Ofrecer públicamente servicios o valores negociables sin la autorización de la CNV","Ofrecer valores en forma privada a pocas personas, sin medios masivos"],a:2,e:"Ofrecer al público servicios o valores negociables sin autorización de la CNV es oferta irregular.",r:"M3 · P106"}
);
